  ((SELECT id FROM "Titles" WHERE slug = 'frieda-and-gitta'), '«Пиво, минет и — расслабьтесь». Первое интервью неизвестного героя бит-поколения Эриха фон Неффа', 'Материал Сергея Дедовича, посвящённый автору и опубликованный в журнале Дискурс.', 'https://6243612d5980520009703948-discours.netlify.app/articles/culture/pivo-minet-i-rasslabtes-pervoe-intervyu-neizvestnogo-geroya-bit-pokoleniya-eriha-fon-neffa', 0),
