INSERT INTO "BookContexts" (title_id, heading, body, url, sort_order)
VALUES
  ((SELECT id FROM "Titles" WHERE slug = 'irokez'), '«Ирокез» Алексея Колесникова | Год Литературы', 'На сайте Год Литературы опубликовали рассказ «Итака» из сборника «Ирокез» Алексея Колесникова, сопроводив его рецензией от Андрея Мягкова.', 'https://godliteratury.ru/articles/2022/05/19/irokez-alekseia-kolesnikova', 0),
  ((SELECT id FROM "Titles" WHERE slug = 'irokez'), 'Интервью с Алексеем Колесниковым', 'В День рождения А.С. Пушкина на Красной площади вручали премии молодым авторам, среди которых в этом году был и Алексей Колёсников: его сборник «Ирокез» оценили по достоинству, отметив 3-м почётным местом. Мы пообщались с Алексеем о премии и о его творчестве.', 'https://vk.com/@ichtivo-intervu-s-alekseem-kolesnikovym', 1);
INSERT INTO "BookContexts" (title_id, heading, body, url, sort_order)
VALUES
  ((SELECT id FROM "Titles" WHERE slug = 'kubok-voiny-i-tanca'), 'Правила смерти Оганеса Мартиросяна', 'В рубрике «Правила смерти» мы расспрашиваем на эту тему замечательных людей нашего времени. О своих правилах смерти рассказывает драматург, поэт, писатель Оганес Мартиросян.', 'https://vk.com/@russiantrex-pravila-smerti-oganesa-martirosyana', 0),
