  ((SELECT id FROM "Titles" WHERE slug = 'overdrive'), 'Антироман «Овердрайв» — секс, наркотики, рок-н-ролл, иногда в другом порядке | журнал ROCKWEEK', 'Читайте первый большой материал об «Овердрайве» Сергея Иннера в журнале ROCKWEEK. Автор текста — Виктория Травникова.', 'https://rockweek.ru/antiroman-overdrive/', 0),
  ((SELECT id FROM "Titles" WHERE slug = 'overdrive'), 'Рецензия на роман Сергея Иннера «Овердрайв»', 'Читайте рецензию автора «Янгспейс» и писателя Василия Вялого на роман Сергея Иннера — «Овердрайв».', 'https://youngspace.ru/culture/retsenziya-na-roman-sergeya-innera-overdrajv', 1),
